  myBrandNewElement.getAttribute(`value`)}`);
console.log(`myBrandNewElement.value => ${myBrandNewElement.value}`);

// the elements outerHTML doesn't show the 'value' property 
console.log(`myBrandNewElement.outerHTML => ${myBrandNewElement.outerHTML}`);

