sha1 not returning correctly

The SHA-1 invocation below has two problems: it returns an incorrect hash, and the hash length is one character shorter than expected. I found this code in this Stack Overflow answer.

#include <string>
#include <iostream>
#include <openssl/sha.h>
#include <ostream>

std::string sha1(const char *in) {
  const unsigned char *uChar = reinterpret_cast<const unsigned char *>(in);
  unsigned char hash[SHA_DIGEST_LENGTH];
  SHA1(uChar, sizeof(uChar), hash);

  for (size_t i = 0; i < SHA_DIGEST_LENGTH; ++i) {
    std::cout << std::hex << (int)hash[i];
  }
  std::cout << std::endl;
  return std::string{reinterpret_cast<char *>(hash)};
}

int main() {
    sha1("Hi");
}

